[InitializeOnLoad]public static class MountainFenceSteelFinish{const string D="Assets/Scenes/Oasis/CoastalTerrain/RoadFence";static MountainFenceSteelFinish(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("MountainFenceSteelFinish.request"))return;File.Delete("MountainFenceSteelFinish.request");try{int meshes=0,rails=0;foreach(var id in AssetDatabase.FindAssets("t:Mesh",new[]{D})){var m=AssetDatabase.LoadAssetAtPath<Mesh>(AssetDatabase.GUIDToAssetPath(id));var flags=new List<Vector4>();m.GetUVs(1,flags);var p=m.vertices;var normal=m.normals;var colors=m.colors;var uv=m.uv;var sums=new Dictionary<Vector3Int,Vector3>();var ids=m.triangles;Func<int,Vector3Int> key=k=>new Vector3Int(Mathf.RoundToInt(p[k].x*10000),Mathf.RoundToInt(p[k].y*10000),Mathf.RoundToInt(p[k].z*10000));for(int k=0;k<ids.Length;k+=3){int a=ids[k],b=ids[k+1],c=ids[k+2];if(flags[a].z<.7f)continue;var n=Vector3.Cross(p[b]-p[a],p[c]-p[a]);foreach(int v in new[]{a,b,c}){var q=key(v);sums[q]=sums.TryGetValue(q,out var old)?old+n:n;}}for(int k=0;k<p.Length;k++)if(flags[k].z>.7f){normal[k]=sums[key(k)].normalized;flags[k]=new Vector4(flags[k].x,flags[k].y,.95f,1);uv[k]=new Vector2(.31f,.10f);colors[k]=new Color(.70f,.73f,.76f,1);rails++;}m.SetUVs(1,flags);m.normals=normal;m.uv=uv;m.colors=colors;m.RecalculateTangents();EditorUtility.SetDirty(m);meshes++;}AssetDatabase.SaveAssets();var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/SouthBeach/BeachDetails/Beach furniture existing atlas.mat");if(ShaderUtil.ShaderHasError(mat.shader))throw new Exception("Shared shader compilation failed");var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,new Vector3(817,31,205),new Vector3(827,29,250),"Mountain-Side-Stainless-Steel-Fence"});File.WriteAllText("FinalEnvironmentRoadReview/MountainFenceSteelFinish.txt","SUCCESS stainless finish on "+meshes+" existing near/far fence mesh assets; rail vertices="+rails+"; smoothed cylindrical normals, metallic reflection and specular, original Building02 atlas and single shared material reused. Existing posts/placement/LODs/mountain unchanged; shader errors=0.");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/MountainFenceSteelFinish.txt",e.ToString());Debug.LogException(e);}}}
